function solve(target, x) {
  if (target === 0) return 0;
  if (target === 1) return 1;
  let res = 0;
  let power = 0;
  let val = x;
  while (val < target) {
    val *= x;
    power++;
  }
  if (val === target) return power;
  let left = solve(target - (val / x), x) + power;
  let right = solve(val - target, x) + power;
  return Math.min(left, right) + 1;
}
